            mistakes: "أخطر غلطة: ترتيب [[-delete]]. find بيقرا الأمر من الشمال لليمين، فلو كتبت [[-delete]] قبل الشروط، هيمسح كل حاجة قبل ما يوصل للشروط أصلًا. حطه في آخر الأمر دايمًا، وشغّل الأمر الأول من غيره عشان تشوف القايمة، وبعدين ضيفه. ونسيان علامات التنصيص حوالين النجمة زي ما شرحنا."
