          sol: R`[[find ~ -type d -name node_modules -prune]] بيطبع مسار كل فولدر node_modules، و [[-prune]] بيمنعه يدخل جوه كل واحد ويلاقي node_modules متداخلة جواه (من غيرها هتلاقي مئات السطور). والحجم: [[find ~ -type d -name node_modules -prune -exec du -sh {} + | sort -h]]، هيطلع حجم جنب كل مسار زي [[312M  /home/ali/shop/node_modules]]، والأكبر في الآخر.

الأمرين دول بيقروا بس. متحطش [[-delete]] ولا [[-exec rm]] في الآخر وانت بتجرّب، لأن المسح من غير رجوع. لو عايز تمسح واحد، امسحه بإيدك بعد ما تشوف مساره، وتقدر ترجّعه بـ [[npm install]] في المشروع ده. ولو ظهرلك [[Permission denied]] كتير، زوّد [[2>/dev/null]].`
