          sol: R`هيطلعلك لحد 5 سطور، كل واحد رقمه في الـ history والأمر، زي [[  512  git status]]. وغالبًا آخر سطر هيبقى الأمر نفسه اللي لسه كاتبه ([[history | grep git | tail -5]])، لأن فيه كلمة git، والأمر بيتسجّل في الـ history قبل ما يتنفّذ.

لو مطلعش حاجة يبقى مكتبتش git في الترمنال ده ولا اتحفظ في [[~/.bash_history]]. ولو عايز تشيل سطر الأمر نفسه: [[history | grep git | grep -v history | tail -5]]. وعلى zsh في الماك [[history]] لوحدها بتعرض آخر 16 بس، فاكتب [[history 1 | grep git | tail -5]].`
