            how: R`[[>]] بتقول للشيل «ودّي الناتج للملف ده بدل الشاشة». لو الملف مش موجود بيتعمل، ولو موجود بيتمسح اللي فيه ويتكتب من الأول.

و [[>>]] نفس الحاجة، بس بتضيف في آخر الملف من غير ما تمسح.

وهنا تفصيلة لازم تفهمها عشان هتنقذك من كارثة: الشيل بيجهّز الملف قبل ما يشغّل الأمر. يعني لما تكتب [[sort data.txt > data.txt]]، الشيل الأول بيفتح data.txt للكتابة ويفضّيه، وبعدين يشغّل [[sort]] اللي بيقرا ملف... فاضي. النتيجة: الملف اتمسح. عمر ما تقرا من ملف وتكتب فيه بـ [[>]] في نفس الأمر. اكتب لملف تاني وبعدين انقله: [[sort data.txt > sorted.txt]].`,
