            how: R`[[curl]] بيعمل بالظبط اللي المتصفح بيعمله لما تفتح لينك: يبني طلب HTTP، ويبعته، ويستلم الرد. بس بدل ما يرسم الصفحة، بيطبع الرد نص زي ما هو.

الافتراضي إنه يبعت GET ويطبع البودي بس. وبالاختيارات بتتحكم في كل جزء من الطلب: [[-X]] نوع الطلب (POST أو PUT أو DELETE)، و [[-H]] تضيف header، و [[-d]] تبعت بيانات في البودي، ولما تستخدمها curl بيحوّل الطلب لـ POST لوحده.

وفي الرد: [[-i]] يوريك الـ status والـ headers قبل البودي، و [[-I]] يوريك الـ headers بس. و [[-L]] مهمة جدًا: لو الموقع بيحوّلك لعنوان تاني (301)، curl مش بيتبعه لوحده، فهتلاقي رد قصير فيه «Moved» أو فاضي بدل الصفحة الحقيقية. [[-L]] بيخليه يتبع التحويل زي المتصفح.

و [[-s]] بيخفي شريط التحميل، و [[-f]] بيخليه «يفشل» لو الرد 4xx أو 5xx، ودي مفيدة في السكربتات عشان تعرف إن فيه مشكلة.`,
