            how: R`[[ping]] بيبعت رسالة صغيرة جدًا للجهاز التاني بتقول «انت موجود؟»، والجهاز بيرد «أيوه». و [[ping]] بيقيس الوقت من ساعة ما بعت لحد ما الرد وصل، وده اللي بيظهر في الآخر بالـ ms (جزء من ألف من الثانية).

أقل من 50ms ممتاز. 100 لـ 200 عادي لسيرفر في قارة تانية. أكتر من كده والاتصال بطيء. ولو فيه رسايل مرجعتش خالص، ده اسمه packet loss، والنسبة بتظهر في الآخر.

وأول حاجة [[ping]] بيعملها إنه يحوّل الدومين لـ IP، فلو اشتغل، بتعرف كمان إن الـ DNS شغال.

و [[-c 4]] بيوقفه بعد ٤ مرات. من غيره هيفضل شغال لحد Ctrl+C.`,
