          cmd: "scp / rsync",
          title: "انقل ملفات من وإلى السيرفر",
          desc: R`الاتنين بينقلوا ملفات بين جهازك والسيرفر فوق ssh، والمسار على السيرفر بيتكتب بعد اسمه ونقطتين: [[root@IP:/var/www/]]. أول حاجة المصدر وبعدين الهدف، فالرفع والتنزيل نفس الأمر بترتيب معكوس، و [[.]] يعني «هنا».

[[scp]] بسيط: بينسخ كل حاجة كل مرة. [[rsync]] أذكى: بيقارن وينقل اللي اتغير بس، فتاني مرة بتاخد ثواني. [[-a]] بيحافظ على الصلاحيات والتواريخ والفولدرات، و [[-v]] يوريك بيعمل إيه، و [[-z]] يضغط وهو بينقل، و [[--exclude node_modules]] يستبعد، و [[--dry-run]] يوريك هينقل إيه من غير ما ينقل.

في rsync الـ [[/]] في آخر المصدر بتفرق: [[./]] أو [[src/]] ينقل اللي جوه، و [[src]] ينقل الفولدر نفسه. جرّب بـ [[--dry-run]] الأول دايمًا.`,
