          desc: R`[[printf]] بيطبع زي echo، بس بقالب (format) بتحدد فيه شكل الناتج بالظبط. أول argument القالب، وجواه أماكن فاضية بتتملي بالقيم اللي بعده بالترتيب: [[%s]] نص، و [[%d]] رقم صحيح، و [[%.2f]] رقم بكسر بعدد أرقام معين بعد العلامة.

وعلى عكس echo، printf مش بينزل سطر لوحده، فلازم تكتب [[\n]] في القالب، و [[\t]] مسافة Tab. والرقم بين [[%]] والحرف عرض الخانة: [[%5d]] الرقم ياخد ٥ خانات ومحاذي يمين، و [[%-10s]] النص ياخد ١٠ خانات ومحاذي شمال (الشرطة)، وده بيعمل أعمدة متساوية. و [[%03d]] بيملا بأصفار. ولو اديته قيم أكتر من الأماكن بيكرر القالب، و [[-v NUM]] بيحط الناتج في متغير بدل ما يطبعه.

ليه مش [[echo -e]]؟ لأن سلوك echo مع [[-e]] و [[\n]] بيختلف: [[sh]] على أوبونتو بيطبع [[-e]] نفسها كلام، و zsh على الماك بيفهم [[\n]] من غيرها. printf بيطلع نفس الناتج في كل شيل، عشان كده هو اللي تستخدمه في السكربتات.`,
