            why: R`echo كفاية لرسالة بسيطة. بس أول ما تحتاج جدول أعمدته محاذية، أو رقم بعدد كسور محدد، أو رقم بأصفار في الأول لاسم ملف ([[img-007.jpg]])، أو سكربت يطلع نفس الناتج على كل جهاز، echo بيتعبك.`,
