            how: R`[[find]] (درسه في المستوى ٢) بيمشي في كل الفولدرات. افتراضيًا بيطبع كل اسم في سطر، ودي مشكلة لو اسم فيه سطر جديد. [[-print0]] بيحط NUL بعد كل اسم، وده الحرف الوحيد اللي مستحيل يبقى جوه اسم ملف.

[[read -d '']] معناها «الفاصل حرف فاضي»، و bash بيفهمها NUL. و [[read]] بيرجع فشل لما مفيش حاجة تتقري، فاللوب بيقف لوحده.

و [[< <(...)]] اسمها process substitution: [[<(find ...)]] bash بيشغّل find ويدّيك مسار زي [[/dev/fd/63]] بيقرا من ناتجه، و [[<]] اللي قبلها بتوجّهه لـ done زي [[< file]]. والميزة إن اللوب بيفضل في الشيل الأصلي، فـ count بعده فيه العدد الصح.

مع الـ pipe، كل جزء بيشتغل في عملية لوحده، واللوب بيعدّ في نسخة من count بتموت لما اللوب يخلص.

والبدايل: [[find . -name "*.log" -exec gzip {} +]] لو كل اللي محتاجه أمر واحد على كل الملفات، و [[find ... -print0 | xargs -0 ...]] (درس xargs).`,
