            mistakes: R`[[for f in $(find ...)]]: بيقسم على المسافات وبيبوّظ أي اسم فيه مسافة. و [[find | while read]] وبعدين تستغرب العدّاد صفر. ونسيان [[-d '']] مع [[-print0]]، فكل الأسامي بتتقري كأنها اسم واحد. ولو جوه اللوب أمر بيقرا من الـ stdin (زي ssh أو ffmpeg)، هياكل باقي الأسامي؛ ادّيله [[< /dev/null]].`
