          sol: R`بيطبع [[Large file: ./sub dir/big file.bin (2.0M)]] و [[Total: 1]]: الاسم وصل كامل بالمسافتين. ولو حطيت ملفات تانية أكبر من 1M هتظهر كلها، من أي فولدر جوه.

وبعد التغيير لـ [[find . -type f -size +1M -print0 | while IFS= read -r -d '' f; do ... done]] هتلاقي سطر [[Large file]] زي ما هو، بس [[Total: 0]]: اللوب عدّ صح جوه الـ subshell، والعدّاد اللي بيتطبع بعده هو نسخة الشيل الأصلي اللي ماتغيرتش. ولو مطلعش ولا ملف، اتأكد إن الملف فعلًا أكبر من 1M ([[ls -lh]])، لأن [[-size +1M]] بيقرّب الحجم لميجا كاملة.`
