          title: "فانكشنز",
          desc: R`الفانكشن مجموعة أوامر ليها اسم، تعرّفها مرة وتناديها كتير: [[log() { ...; }]] وبعدها [[log "Started"]] زي أي أمر. ولازم تتعرّف قبل ما تتنادى، لأن bash بيقرا من فوق لتحت.

الكلام اللي بعد اسمها بيوصلها في [[$1]] و [[$2]] و [[$*]] (كلهم)، ودول بتوعها هي مش بتوع السكربت. و [[local]] بيخلي المتغير جوه الفانكشن بس؛ من غيرها أي متغير بتعمله بيبقى عام وممكن يكتب فوق متغير في السكربت.

الفانكشن ملهاش return value زي JavaScript. [[return]] بترجع exit code بس (0 نجاح، وأي رقم تاني فشل)، فتستخدمها في [[if]] أو [[||]]. ولو عايز ترجع قيمة اطبعها بـ [[echo]] وخدها بـ [[$( )]]، زي [[SIZE=$(folder_size /var/www)]] في المثال. ولما الفانكشنز تتكرر بين كذا سكربت، شوف درس [[source lib.sh]].`,
          example: R`#!/usr/bin/env bash
log() {
  echo "[$(date '+%H:%M:%S')] $*"
}

folder_size() {
  local dir="$1"
  du -sh "$dir" | cut -f1
}

check_dir() {
  if [[ ! -d "$1" ]]; then
    log "Missing: $1"
    return 1
  fi
}

check_dir /var/www || exit 1
SIZE=$(folder_size /var/www)
log "Size is $SIZE"`,
          try: "اعمل فانكشن بتاخد اسم برنامج وتقولك متسطب ولا لأ.",
