          sol: R`[[--dry-run -k 3 logs/]]: [[source=logs/ keep=3 dry_run=1]]. و [[--keep=14 logs]]: [[source=logs keep=14 dry_run=0]]. و [[--help]] بيطبع الشرح بالأربع سطور و exit 0. و [[-k]] لوحدها: [[clean.sh: line 16: 2: --keep needs a number]] و exit 1 (رسالة [[:?]] فيها رقم السطر واسم المتغير 2). و [[--wat x]]: [[Unknown option: --wat]] والشرح و exit 2.

و [[-v|--verbose]]: سطر [[VERBOSE=0]] مع القيم الافتراضية، وفرع [[-v|--verbose) VERBOSE=1 ;;]] قبل [[-*)]]، وسطر في الـ usage. لو حطيت الفرع بعد [[-*)]] هيقولك Unknown option، لأن case بياخد أول فرع يطابق.`
