            how: R`[[confirm]] بترجع exit code مش نص: [[return 0]] يعني أيوه و [[return 1]] لأ، فتستخدمها مباشرة في [[if confirm "..."]] (درس function). و [[local]] بيخلي answer جوه الفانكشن بس. والـ case بنمط [[ [yY] ]] (حرف من الاتنين) ونمط [[ [yY][eE][sS] ]] بيقبل y و Y و yes و YES و Yes.

[[select name in list; do ... done]] لوب: بيطبع القايمة (على stderr)، ويقرا سطر، ولو الرقم في القايمة يحط العنصر في name، ولو لأ يسيبه فاضي. و [[$REPLY]] دايمًا فيه اللي اتكتب بالظبط. ومن غير [[break]] هيفضل يسأل تاني، ولو اليوزر داس Ctrl+D (نهاية الإدخال) اللوب بيخلص لوحده.

ولو المدخل جاي من pipe مش من ترمنال، [[read -p]] مش بيطبع السؤال أصلًا. وتقدر تعرف السكربت شغال قدام إنسان ولا لأ بـ [[-t 0]] جوه الشرط: صح لو الـ stdin ترمنال.`,
