          title: "رسايل info و warn و error ملوّنة",
          desc: R`سكربت محترم بيقولك هو بيعمل إيه، وبيفرق بين المعلومة والتحذير والخطأ. أسهل طريقة ٣ فانكشنز صغيرين: [[info]] و [[warn]] و [[die]]، كل واحدة بتطبع بادئة بلون، و [[die]] كمان بتقفل السكربت بـ [[exit 1]].

الألوان أكواد خاصة الترمنال بيفهمها: [[$'\e[31m']] أحمر، و [[32m]] أخضر، و [[33m]] أصفر، و [[$'\e[0m']] يرجّع اللون العادي. والكتابة [[$'...']] بتخلي bash يحوّل [[\e]] لحرف Escape الحقيقي. والرسايل كلها بتروح لـ stderr بـ [[>&2]]، عشان ناتج السكربت الحقيقي (لو حد عمله pipe) ميتلخبطش بيها، وبتتطبع بـ printf (درس printf) عشان أي [[%]] في الرسالة متبوّظهاش.

الألوان بتتفعّل بس لو stderr ترمنال ([[-t 2]] جوه الشرط) ومفيش متغير [[NO_COLOR]]. لو الرسايل رايحة لملف لوج أو CI، الأكواد هتبان رموز غريبة قبل كل سطر، فبنسيب متغيرات الألوان فاضية.`,
          example: R`#!/usr/bin/env bash
RED="" GREEN="" YELLOW="" RESET=""
if [[ -t 2 && -z "$__{NO_COLOR:-}" ]]; then
  RED=$'\e[31m' GREEN=$'\e[32m' YELLOW=$'\e[33m' RESET=$'\e[0m'
fi
info() { printf '%s[INFO]%s %s\n' "$GREEN" "$RESET" "$*" >&2; }
warn() { printf '%s[WARN]%s %s\n' "$YELLOW" "$RESET" "$*" >&2; }
die()  { printf '%s[ERROR]%s %s\n' "$RED" "$RESET" "$*" >&2; exit 1; }

info "Starting backup"
warn "Disk is 85% full"
[[ -d /var/www ]] || die "/var/www not found"
info "Found /var/www"`,
          try: R`احفظه باسم colors.sh وشغّله في الترمنال وشوف الألوان، وبعدين [[bash colors.sh 2> out.txt]] و [[cat -v out.txt]]، وبعدين [[NO_COLOR=1 bash colors.sh]].`,
