          example: R`#!/usr/bin/env bash
set -uo pipefail
PASS=0; FAIL=0
ok()  { echo -e "  \033[32mok\033[0m   $*"; PASS=$((PASS+1)); }
bad() { echo -e "  \033[31mFAIL\033[0m $*"; FAIL=$((FAIL+1)); }

if [ "$EUID" -eq 0 ]; then SUDO=""; else SUDO="sudo"; fi

[ "$(nproc)" -ge 2 ] && ok "$(nproc) cores" || bad "need 2+ cores"
FREE_GB=$(df -BG --output=avail / | tail -1 | tr -dc '0-9')
[ "$FREE_GB" -ge 20 ] && ok "$FREE_GB GB free" || bad "only $FREE_GB GB free"
command -v docker >/dev/null && ok "docker installed" || bad "docker missing"
$SUDO ss -ltnp | grep -qE '0\.0\.0\.0:5432|\[::\]:5432' && bad "postgres open to the internet" || ok "postgres private"
test -f .env && ok ".env exists" || bad ".env missing"
for k in DOMAIN POSTGRES_PASSWORD; do
  grep -qE "^$k=.+" .env 2>/dev/null && ok "$k set" || bad "$k empty"
done

echo "passed $PASS, failed $FAIL"
[ "$FAIL" -eq 0 ]`,
          try: "شغّله على سيرفر التجربة، وبعدين امسح قيمة DOMAIN من .env وشغّله تاني، واطبع [[echo $?]] بعده.",
