            how: R`ده بيجمع كل حاجة اتعلمتها:

[[set -euo pipefail]]: أي خطوة تفشل، السكربت يقف فورًا، مش هيكمّل ببيانات بايظة.

[[BRANCH]] بقيمة افتراضية [[main]]، فتقدر تعمل deploy لـ branch تانية للتجربة.

فانكشن [[log]] بتطبع السطر على الشاشة، وكمان بتضيفه في ملف [[deploy.log]] بـ [[tee -a]]. فبعد أسبوع تقدر تعرف كل deploy حصل إمتى ونجح ولا لأ.

[[trap ... ERR]] لو أي أمر فشل، يسجّل في اللوج إنه فشل وفي أنهي سطر.

[[git pull --ff-only]] بيسحب التحديثات بس لو ممكن «fast-forward»، يعني من غير merge. لو حد عدّل حاجة على السيرفر نفسه بالغلط، مش هيعمل merge غريب، هيفشل ويقولك.

[[docker image prune -f]] بيمسح الصور القديمة عشان الديسك ميتملاش.

وفي الآخر health check: [[sleep 5]] يستنى التطبيق يقوم، و [[curl -fsS]] بيطلب [[/health]]، و [[-f]] بتخلي curl يفشل لو الرد 4xx أو 5xx. فالسكربت ميقولش «Deploy OK» غير لو الموقع رد فعلًا.`,
