          solCode: R`// في Express:
// app.get("/health", (req, res) => res.json({ status: "ok" }));

// أو من غير أي مكتبة:
const http = require("http");
http.createServer((req, res) => {
  if (req.url === "/health") {
    res.writeHead(200, { "Content-Type": "application/json" });
    return res.end(JSON.stringify({ status: "ok" }));
  }
  res.writeHead(404);
  res.end("not found");
}).listen(3000);`
