          flag: "script",
          mac: ["diff", R`[[$__{new,,}]] محتاج bash 4 (على الماك [[brew install bash]]، أو بدّلها بـ [[tr '[:upper:]' '[:lower:]']]). و [[date -r ملف]] موجودة في date بتاع الماك كمان.`],
