          desc: R`سكربت بيدخل فولدر (الافتراضي [[~/Downloads]]) ويوزّع الملفات في فولدرات حسب الامتداد: الصور في [[Images]]، والـ PDF والمستندات في [[Documents]]، والمضغوط في [[Archives]]، وهكذا، واللي مش معروف في [[Other]].

[[$__{1:-$HOME/Downloads}]] الفولدر من أول argument، ولو مفيش خد Downloads. و [[$__{f##*.}]] الامتداد (درس [[$__{VAR%.*} و $__{VAR##*.}]])، و [[$__{ext,,}]] سمول عشان [[JPG]] و [[jpg]] يبقوا واحد. و [[case]] بيختار الفولدر، و [[jpg|jpeg|png]] يعني أي واحد منهم.

السكربت بينقل بس ومبيمسحش، فكل حاجة ترجع بإيدك لو حبيت. ولو فيه ملف بنفس الاسم في الفولدر الهدف بيسيبه مكانه ويقولك. والملفات اللي من غير امتداد والمخفية والفولدرات مش بيلمسها.`,
          example: R`#!/usr/bin/env bash
# organize.sh [DIR]: رتّب الملفات في فولدرات حسب الامتداد
set -euo pipefail
DIR="$__{1:-$HOME/Downloads}"
cd "$DIR"
shopt -s nullglob

for f in *.*; do
  [[ -f "$f" ]] || continue
  ext="$__{f##*.}"
  case "$__{ext,,}" in
    jpg|jpeg|png|gif|webp|svg) folder="Images" ;;
    pdf|doc|docx|txt|md|xlsx|csv|pptx) folder="Documents" ;;
    zip|tar|gz|tgz|rar|7z) folder="Archives" ;;
    mp4|mkv|mov|mp3|wav|m4a) folder="Media" ;;
    deb|rpm|appimage|exe|msi|dmg|sh) folder="Installers" ;;
    *) folder="Other" ;;
  esac
  mkdir -p "$folder"
  if [[ -e "$folder/$f" ]]; then
    echo "skip (exists): $folder/$f" >&2
  else
    mv -- "$f" "$folder/"
    echo "$f -> $folder/"
  fi
done`,
