          title: "امسح الملفات الأقدم من N يوم، بأمان",
          desc: R`سكربت بيلاقي الملفات اللي آخر تعديل فيها أقدم من عدد أيام في فولدر معين (وكل اللي جواه)، ويعرضها. ومبيمسحش إلا لو كتبت [[--delete]] صريح في الآخر، فأول تشغيل دايمًا بيوريك هيمسح إيه.

[[$__{1:?$USAGE}]] و [[$__{2:?$USAGE}]] بيوقفوا السكربت برسالة الاستخدام لو الفولدر أو الأيام ناقصين. وقبل أي حاجة ٣ فحوصات أمان: الفولدر موجود، والأيام رقم بس ([[=~ ^[0-9]+$]])، والفولدر مش [[/]] نفسه. و [[find -mtime +7]] معناها «أقدم من ٧ أيام كاملة» (يعني ٨ أو أكتر).

الـ find اللي بيمسح هو نفس الـ find اللي بيعرض بنفس الشروط بالظبط، والفرق [[-delete]] بس في الآخر، فاللي شفته هو اللي هيتمسح.`,
          example: R`#!/usr/bin/env bash
# cleanup-old.sh DIR DAYS [--delete]: من غير --delete بيعرض بس
set -euo pipefail
USAGE="Usage: cleanup-old.sh DIR DAYS [--delete]"
DIR="$__{1:?$USAGE}"
DAYS="$__{2:?$USAGE}"
MODE="$__{3:-}"

[[ -d "$DIR" ]] || { echo "Not a folder: $DIR" >&2; exit 2; }
[[ "$DAYS" =~ ^[0-9]+$ ]] || { echo "DAYS must be a number" >&2; exit 2; }
[[ "$(cd "$DIR" && pwd)" != "/" ]] || { echo "Refusing to touch /" >&2; exit 2; }

find "$DIR" -type f -mtime +"$DAYS" -print
COUNT=$(find "$DIR" -type f -mtime +"$DAYS" | wc -l)

if [[ "$MODE" == "--delete" ]]; then
  find "$DIR" -type f -mtime +"$DAYS" -delete
  echo "Deleted $COUNT files older than $DAYS days"
else
  echo "$COUNT files would be deleted. Run again with --delete to delete them."
fi`,
          try: R`في [[~/lab]] اعمل فولدر files وجواه ملفات بتواريخ قديمة: [[touch -d "40 days ago" files/old.log]] و [[touch -d "8 days ago" files/eight.log]] و [[touch files/new.log]]. شغّل [[bash cleanup-old.sh files 7]]، وبعدين [[bash cleanup-old.sh files 30 --delete]]، وبعدين [[ls files]].`,
          flag: "script danger",
          mac: ["both", R`[[find -mtime]] و [[-delete]] شغالين على الماك. و [[touch -d]] في التجربة لينكس بس؛ على الماك [[touch -t 202608200000 files/old.log]] (السنة والشهر واليوم والساعة والدقيقة).`],
