            how: R`الفحوصات اللي في الأول كل واحد سطر: الشرط، وبعده [[||]] وأقواس معقوفة [[{ ...; }]] فيها أكتر من أمر (رسالة وخروج). ده شكل مختصر لـ if.

[[$(cd "$DIR" && pwd)]] بيحوّل أي شكل للمسار ([[.]] أو [[../..]] أو [[/tmp/..]]) للمسار الحقيقي الكامل، فالفحص بيمسك [[/]] حتى لو اتكتب بطريقة ملتوية.

و [[-mtime +7]]: find بيحسب عمر الملف بالأيام الكاملة ويقرّب لتحت، و [[+7]] يعني أكبر من 7، فملف عمره ٧ أيام ونص مش داخل، وعمره ٨ داخل.

و [[-type f]] ملفات بس، فالفولدرات نفسها بتفضل حتى لو فضيت. و [[$COUNT]] بيتحسب قبل المسح عشان يطبع اتمسح كام.

ولو عايز تجربة من غير مسح خالص وانت بتعدّل السكربت، بدّل [[-delete]] بـ [[-print]].`,
            when: "فولدر باك أب (لو مش بيمسح القديم لوحده زي backup.sh)، و [[~/Downloads]]، وفولدرات temp و cache بتاعة أدوات. ومع cron بعد ما تتأكد من الأرقام.",
            mistakes: R`تشغيله على طول بـ [[--delete]] من غير ما تشوف القايمة. ورقم أيام غلط (0 مثلًا معناها أي حاجة أقدم من يوم!). ومتغير فاضي في المسار: من غير [[:?]] لو الـ argument نسيته، [[find ""]] بيطلّع error، بس في سكربتات تانية متغير فاضي في مسار [[rm]] بيبقى كارثة. ونسيان إن [[-mtime]] بيبص على آخر تعديل مش آخر فتح.`
