          sol: R`عادي (على جهاز ديسكه 69%): [[All disks below 85%]] و exit 0. و [[bash disk-alert.sh 5]]: [[WARNING: / is 69% full (limit 5%)]] و exit 1، وسطر تحذير لكل ديسك عدّى الحد (زي [[/boot/efi]] لو موجود ونسبته فوق 5).

لو مطلعش ولا سطر حتى مع 5، يبقى df عندك مطلّعش ديسكات بتبدأ بـ [[/dev/]]، زي جوه container أو WSL (الديسك هناك اسمه [[overlay]] أو [[none]]). شيل شرط [[/dev/]] من awk وجرّب تاني.`
