          sol: R`بيطبع [[before: 1.2M]]، وبعدين أسامي اللوجات اللي اتضغطت ([[logs/app-3.log]] و [[logs/app-10.log]] و [[logs/app-45.log]])، وبعدين [[logs/app-45.log.gz]] اللي اتمسح، وفي الآخر حاجة زي [[after:  504K]] (الترتيب والأرقام ممكن يختلفوا شوية). و [[ls -l logs]] بيوريك [[app-1.log]] زي ما هو (عمره يوم واحد بس) و [[app-3.log.gz]] و [[app-10.log.gz]] بتواريخهم الأصلية.

التشغيلة التانية مبتطبعش أسامي والحجم مبيتغيرش، لأن مفيش جديد. ولو [[app-1.log]] اتضغط، يبقى [[touch -d]] اتكتب غلط والتاريخ أقدم من المقصود.`
