          title: "شغّل سكربتاتك لوحدها بمواعيد",
          desc: R`آخر خطوة في الأتمتة إن السكربت يشتغل لوحده: الباك أب كل يوم الساعة ٣، وفحص الموقع كل ٥ دقايق. ده شغل cron: [[crontab -e]] بيفتح جدول مهامك، وكل سطر فيه ٥ خانات للوقت (دقيقة، ساعة، يوم في الشهر، شهر، يوم في الأسبوع) وبعدين الأمر. [[0 3 * * *]] كل يوم ٣:٠٠، و [[*/5 * * * *]] كل ٥ دقايق، و [[0 * * * *]] أول كل ساعة. والصيغة بالتفصيل في دروس crontab في تاب VPS.

cron بيشغّل سكربتك في بيئة فقيرة: الـ PATH فيه [[/usr/bin:/bin]] بس، ومن غير [[.bashrc]]، والفولدر الحالي هو الـ home. فاكتب مسارات كاملة، وجرّب السكربت الأول في بيئة شبهها: [[env -i]] بيشغّل الأمر بمتغيرات البيئة اللي انت تحددها بس.

و [[>> ملف 2>&1]] في آخر كل سطر بيحفظ الناتج والأخطاء في لوج، لأن مفيش شاشة. و [[flock -n ملف.lock]] بيمنع تشغيلتين من نفس السكربت في نفس الوقت: لو القديمة لسه شغالة، الجديدة بتخرج على طول.`,
          example: R`mkdir -p ~/logs
env -i HOME="$HOME" PATH=/usr/bin:/bin bash ~/bin/backup.sh ~/projects
crontab -e
# السطور اللي هتضيفها في الملف اللي اتفتح:
0 3 * * * flock -n /tmp/backup.lock $HOME/bin/backup.sh $HOME/projects >> $HOME/logs/backup.log 2>&1
*/5 * * * * $HOME/bin/site-check.sh https://example.com >> $HOME/logs/site.log 2>&1
0 * * * * $HOME/bin/disk-alert.sh 90 >> $HOME/logs/disk.log 2>&1
crontab -l
tail -n 20 ~/logs/backup.log`,
