            why: "على سيرفر فيه Nginx جوه container، وملف الإعداد متركّب من الجهاز. عدّلته بـ [[sed -i]] وعملت reload، والتغيير مظهرش. تفتح الملف تلاقيه متعدّل، وتدخل الـ container تلاقيه القديم. ده مش bug في Docker، ده الـ inode.",
            how: R`الاسم في الفولدر مجرد لافتة بتشاور على inode، والـ inode هو الملف الحقيقي (بياناته ومكانه على الديسك). [[ls -i]] بيطبع رقمه.

لما تعمل bind mount لملف واحد، Docker بيربط الـ inode ده بالمسار اللي جوه الـ container ساعة ما الـ container بيقوم، ومن بعدها مش بيبص على الاسم تاني.

[[sed -i]] مش بيعدّل الملف في مكانه: بيكتب ملف مؤقت جديد وبعدين يعمل له rename باسم القديم. نفس الحكاية مع [[mv]]، ومع محررات كتير لما بتحفظ. النتيجة inode جديد، والاسم على الجهاز بقى بيشاور عليه، بس الـ container لسه ماسك القديم.

[[cat new > file]] مختلفة: [[>]] بيفتح الملف الموجود ويفضّيه ويكتب فيه، فالـ inode هو هو والـ container يشوف الكلام الجديد فورًا.

والأحسن متكتبش على الإعداد الشغال قبل ما تجربه: جرّب النسخة الجديدة في container مؤقت ([[docker run --rm -v /tmp/nginx.new:/etc/nginx/nginx.conf:ro nginx nginx -t]]) وبعدين اكتبها. ولو لقيت الرقمين مختلفين أصلًا، reload مش هيفيد، لازم restart عشان الـ mount يتعمل من جديد.

وأسهل حل من الأول: اعمل mount لفولدر مش لملف واحد ([[./nginx/conf.d:/etc/nginx/conf.d]]). الفولدر بيتشاف بالأسامي، فأي طريقة تعديل بتشتغل.`,
