            how: R`[[tar -czf -]]: الشرطة مكان اسم الملف معناها «اكتب الأرشيف على الـ stdout»، فيدخل في الـ pipe على طول.

[[openssl enc]] بيشفّر اللي داخله: [[-aes-256-cbc]] نوع التشفير، و [[-salt]] بيضيف قيمة عشوائية فنفس الملف بنفس الباسورد يطلع مختلف كل مرة. و [[-pbkdf2 -iter 200000]] أهم جزء: بيحوّل الباسورد لمفتاح بعد ٢٠٠ ألف لفة حساب، فتخمين الباسورد يبقى بطيء جدًا. من غيرهم openssl بيستخدم طريقة قديمة سريعة وبيطلع تحذير «deprecated key derivation».

وفك التشفير نفس الأمر بـ [[-d]] وبنفس الفلاجات بالظبط، وإلا هيطلع «bad decrypt». و [[tar -tzf -]] في المثال بيعرض محتوى الأرشيف من غير ما يفكه، فتتأكد إن الباك أب سليم. للفك الحقيقي [[tar -xzf -]].

والباسورد: [[-pass pass:secret]] بيحط الباسورد في arguments البرنامج، وأي يوزر على السيرفر يقدر يشوفها بـ [[ps aux]] طول ما الأمر شغال. [[env:NAME]] بيقراه من متغير بيئة، و [[file:path]] من ملف، والاتنين مش بيبانوا.

وخلي بالك إن CBC مفيهاش فحص تلاعب: لو حد غيّر بايتات في الملف، هيتفك لحاجة بايظة من غير ما يقولك. لو محتاج ده، [[age]] أو [[gpg]] أحسن.`,
            when: "أي باك أب لقاعدة بيانات أو ملفات عملاء هيطلع برّه السيرفر: S3، أو Drive بـ rclone، أو حتى جهازك.",
            mistakes: R`في مشروع حقيقي كان سكربت الباك أب مكتوب فيه [[-pass "pass:$PASS"]]، فالباسورد بيبان في [[ps]] لأي يوزر على السيرفر وقت ما cron بيشغّله. وأشهر مصيبة: الباسورد متخزن على السيرفر بس، فلو السيرفر راح، الباك أب اللي برّه مالوش لازمة. احفظ نسخة في مدير باسوردات. وباك أب عمرك ما جربت تفكه زي مفيش: جرّب أمر الفك كل فترة.`
