          sol: R`التشفير مش بيطبع حاجة، و [[file lab.tar.gz.enc]] بيقول [[openssl enc'd data with salted password]]. بباسورد غلط والخرج رايح لـ tar، غالبًا أول حاجة هتشوفها [[gzip: stdin: not in gzip format]] من tar، لأن اللي طلع كلام ملخبط. عشان تشوف رسالة openssl لوحدها وجّه الخرج لـ [[/dev/null]] زي الكود: [[bad decrypt]] وسطر تحته فيه [[bad decrypt]] تاني، و exit 1. بالباسورد الصح [[tar -tzf -]] بيعرض [[lab/]] والملفات اللي جواه.

وارد (نادرًا) إن باسورد غلط يعدّي من غير bad decrypt ويطلّع كلام ملخبط، وعشان كده الـ tar في الآخر مهم: هو اللي بيأكد إن اللي اتفك سليم. ولو bad decrypt ظهر مع الباسورد الصح، اتأكد إن [[-pbkdf2]] و [[-iter]] زي التشفير بالظبط، أو إنك مش على ماك بـ LibreSSL قديم.`,
          solCode: R`export BACKUP_PASSPHRASE="$(cat ~/.backup-pass)"
tar -czf - -C ~ lab | openssl enc -aes-256-cbc -pbkdf2 -iter 200000 -salt -pass env:BACKUP_PASSPHRASE -out lab.tar.gz.enc
BACKUP_PASSPHRASE=wrong openssl enc -d -aes-256-cbc -pbkdf2 -iter 200000 -pass env:BACKUP_PASSPHRASE -in lab.tar.gz.enc -out /dev/null
openssl enc -d -aes-256-cbc -pbkdf2 -iter 200000 -pass env:BACKUP_PASSPHRASE -in lab.tar.gz.enc | tar -tzf - | head`
