          desc: R`[[-o /dev/null -w '%{http_code}']] بيرمي الصفحة ويطبع الـ status code بس، فتحطه في متغير وتقارنه. لوب على الصفحات المهمة بعد كل ديبلوي، والسكربت يطلع بفشل لو صفحة رجعت غير المتوقع، بما فيهم إن صفحة مش موجودة ترجع 404 فعلًا.`,
          example: R`SITE="https://example.com"
fail=0
for path in / /login /contact /api/health /this-should-404; do
  code=$(curl -s -o /dev/null --max-time 10 -w '%{http_code}' "$SITE$path")
  want=200; [ "$path" = "/this-should-404" ] && want=404
  echo "$code $path"
  [ "$code" = "$want" ] || fail=1
done
exit $fail`,
