            how: R`[[-o /dev/null]] بيرمي البودي، و [[-s]] بيخفي شريط التقدم، و [[-w '%{http_code}']] بيطبع بعد ما الطلب يخلص الـ status code بس. فالمتغير [[code]] بيبقى فيه 200 أو 404، أو 000 لو مقدرش يوصل أصلًا.

[[--max-time 10]] مهم: من غيره سيرفر بطيء أو معلّق بيخلي السكربت يستنى للأبد.

ليه مش [[curl -f]]؟ [[-f]] بيقولك «فشل» لأي 4xx، بس هنا انت عايز 404 في صفحة معينة. لما بتقارن الرقم بنفسك بتقدر تقول بالظبط انت متوقع إيه. والـ 404 المقصودة مهمة: لو الموقع بيرجع 200 لكل حاجة، يبقى فيه rewrite غلط بيخبّي الأخطاء.

والسكربت مش بيقف عند أول فشل، بيكمّل ويطبع كل النتايج، وفي الآخر [[exit $fail]] يرجع 1 لو أي صفحة فشلت، فـ CI أو make يعرفوا.

ولو محتاج الكود والبودي الاتنين (عشان تطبع رسالة الخطأ): [[curl -s -w '\n%{http_code}']] بيحط الكود في آخر سطر، وبعدين [[tail -n1]] يجيب الكود، و [[sed '$d']] يجيب كل حاجة إلا آخر سطر.`,
