          sol: R`على موقع شغال: سطر لكل صفحة زي [[200 /]] و [[200 /login]] و [[404 /this-should-404]]، و [[echo $?]] = 0. بعد ما تضيف صفحة غلط زي [[/wrong-page]] للستة: [[404 /wrong-page]] و [[echo $?]] = 1، لأن الكود مش زي المتوقع (200) فبقى [[fail=1]]. والـ 404 على [[/this-should-404]] نجاح هنا، لأن السكربت متوقعها.

لو شفت [[301]] أو [[308]] بدل 200، الصفحة بتحوّل (مثلًا [[/login]] لـ [[/login/]])؛ يا إما تكتب المسار النهائي، يا إما تزوّد [[-L]]. ولو كله [[000]] يبقى curl موصلش خالص (دومين غلط أو الموقع واقع أو timeout). ولو الصفحة الغلط رجعت 200، يبقى الموقع (غالبًا SPA) بيرجّع index.html لأي مسار، ودي مشكلة تستاهل تتصلّح.`
